"""Contract tests generated by repo-autopilot.

The model-written tests contradicted this project's implementation, so these
tests are derived from the code itself: every module has to import cleanly and
every public function has to exist and be callable.
"""

import importlib

import pytest

MODULES = ["code_review_tool"]


def test_every_module_imports():
    for name in MODULES:
        assert importlib.import_module(name) is not None

PUBLIC_API = [
    ("code_review_tool", "review_code_snippet"),
]


@pytest.mark.parametrize(("module", "function"), PUBLIC_API)
def test_public_function_is_callable(module, function):
    imported = importlib.import_module(module)
    assert callable(getattr(imported, function, None))
